\begin{theorem}\label{strongmg} 
For any mixed graph $G=(V,E,A)$ and positive integer $k$, $(-1)^{|V|} \widehat{\chi}_G(-k)$ equals the number of $k$-colorings of $G$, each counted with multiplicity equal to the number of compatible acyclic orientations of~$G$.
\end{theorem}

