\begin{proof}[Proof of Theorem \ref{main}]
If $G$ is an acyclic mixed graph, then by Lemma \ref{phisum},
\begin{eqnarray*}
\chi_G(-k) &=& \displaystyle\sum_{i=1}^m \phi_{G_i}(-k) \\
&=& \displaystyle\sum_{i=1}^m \Omega_{P_i,\omega_i}(-k) \ \text{ (by Lemma \ref{labeling})}\\
&=& \displaystyle\sum_{i=1}^m (-1)^{|P_i|}\Omega_{P_i,\overline{\omega_i}}(k) \ \text{ (by Theorem \ref{stanley_op})}\\
&=& (-1)^{|V|}\displaystyle\sum_{i=1}^m \Omega_{P_i,\overline{\omega_i}}(k) \, . 
\end{eqnarray*}
By applying Lemma \ref{labeling} again, the proof is completed.
\end{proof}

